// Package docs generates the documentation site pages for every rule from the rule registry,
// so the published docs always match the rules the binary exposes.
package docs

import (
	"fmt"
	"sort"
	"strings"

	"github.com/danielsada/go-ado-pipelines-lint/internal/expr"
	"github.com/danielsada/go-ado-pipelines-lint/internal/lint"
	"github.com/danielsada/go-ado-pipelines-lint/internal/rules"
	"github.com/danielsada/go-ado-pipelines-lint/internal/schema"
	"github.com/danielsada/go-ado-pipelines-lint/internal/scripts"
)

// Header marks generated files.
const Header = "<!-- Code generated by `make docs` (go run ./cmd/gendocs docs); DO NOT EDIT. -->\n"

// categories lists rule groups in display order.
var categories = []string{"Syntax and schema", "Structure and identity", "Templates and parameters",
	"Expressions", "Best practices", "Tasks", "Conditions", "Scripts"}

// emitters describes, for rules without their own checker, which component reports them.
var emitters = map[string]string{
	"ADO001": "the YAML parser, for every linted file and template",
	"ADO002": "the YAML parser, for every linted file and template",
	"ADO003": "schema validation of the template-expanded pipeline",
	"ADO005": "schema validation of the template-expanded pipeline",
	"ADO006": "schema validation of the template-expanded pipeline",
	"ADO007": "schema validation of the template-expanded pipeline",
	"ADO201": "template expansion",
	"ADO202": "template expansion",
	"ADO203": "template expansion",
	"ADO204": "template expansion",
	"ADO205": "template expansion",
	"ADO208": "template expansion",
	"ADO501": "schema validation of task steps in the expanded pipeline",
	"ADO502": "schema validation of task steps in the expanded pipeline",
	"ADO503": "schema validation of task steps in the expanded pipeline",
	"ADO701": "ShellCheck, run on inline bash scripts extracted from the expanded pipeline",
	"ADO702": "PSScriptAnalyzer, run on inline PowerShell scripts extracted from the expanded pipeline",
	"ADO703": "script linting, when a linter can't be run",
}

// Generate returns the generated pages, keyed by path relative to the docs directory.
func Generate() (map[string]string, error) {
	reg := rules.Registry()
	v, err := schema.NewValidator()
	if err != nil {
		return nil, err
	}
	out := map[string]string{"rules/index.md": index(reg)}
	for i, r := range reg.All() {
		out["rules/"+r.Meta().ID+".md"] = page(r, i+1, v)
	}
	return out, nil
}

func checkedBy(r lint.Rule) string {
	switch r.(type) {
	case lint.SourceRule:
		return "each original source file, before template expansion"
	case lint.PipelineRule:
		return "the template-expanded pipeline (positions point at the original files)"
	}
	if e, ok := emitters[r.Meta().ID]; ok {
		return e
	}
	return "adolint"
}

func defaultState(m *lint.Meta) string {
	if m.DisabledByDefault {
		return "no (enable with `--enable " + m.ID + "` or in `.adolint.yaml`)"
	}
	return "yes"
}

func severityText(m *lint.Meta) string {
	switch m.ID {
	case "ADO701", "ADO702":
		return "per finding (the tool's own severity)"
	}
	return m.Severity.String()
}

func page(r lint.Rule, order int, v *schema.Validator) string {
	m := r.Meta()
	var b strings.Builder
	fmt.Fprintf(&b, "---\ntitle: \"%s %s\"\nparent: Rules\nnav_order: %d\npermalink: /rules/%s/\n---\n%s{%% raw %%}\n", m.ID, m.Name, order, m.ID, Header)
	fmt.Fprintf(&b, "# %s: %s\n\n%s\n\n", m.ID, m.Name, m.Summary)
	b.WriteString("| | |\n| --- | --- |\n")
	fmt.Fprintf(&b, "| **Category** | %s |\n| **Default severity** | %s |\n| **Enabled by default** | %s |\n| **Checked on** | %s |\n\n",
		m.Category(), severityText(m), defaultState(m), checkedBy(r))
	fmt.Fprintf(&b, "## Description\n\n%s\n\n", m.Description)
	if extra := details(m.ID, v); extra != "" {
		b.WriteString(extra + "\n")
	}
	if m.Bad != "" || m.Good != "" {
		b.WriteString("## Example\n\n")
		if m.Bad != "" {
			fmt.Fprintf(&b, "Problem:\n\n```yaml\n%s\n```\n\n", m.Bad)
		}
		if m.Good != "" {
			fmt.Fprintf(&b, "Instead:\n\n```yaml\n%s\n```\n\n", m.Good)
		}
	}
	fmt.Fprintf(&b, "## Configuration\n\nChange the severity or turn the rule off in `.adolint.yaml`:\n\n```yaml\nrules:\n  %s: %s   # off | info | warning | error\n```\n\n", m.ID, configExample(m))
	fmt.Fprintf(&b, "Or on the command line: `adolint lint --disable %s` or `--enable %s`.\n\n", m.ID, m.ID)
	fmt.Fprintf(&b, "Suppress a single finding with a comment on the line before it (or `disable-line` at the end of the line):\n\n```yaml\n# adolint:disable-next-line %s\n```\n\n", m.ID)
	if m.HelpURI != "" {
		fmt.Fprintf(&b, "## References\n\n- <%s>\n\n", m.HelpURI)
	}
	fmt.Fprintf(&b, "## Questions and feedback\n\nQuestions about %s, or a false positive? [Open an issue](%s/new?title=%s%%3A+) with the YAML that triggered it.\n", m.ID, lint.IssuesURL, m.ID)
	b.WriteString("{% endraw %}\n")
	return b.String()
}

func configExample(m *lint.Meta) string {
	if m.DisabledByDefault {
		return m.Severity.String()
	}
	return "off"
}

// details returns extra sections generated from the data the rule uses.
func details(id string, v *schema.Validator) string {
	switch id {
	case "ADO302":
		var b strings.Builder
		b.WriteString("### Known functions\n\n| Function | Arguments |\n| --- | --- |\n")
		for _, f := range expr.Funcs() {
			kind := ""
			if f.Status {
				kind = " (job status check)"
			}
			fmt.Fprintf(&b, "| `%s`%s | %s |\n", f.Name, kind, f.Arity())
		}
		return b.String()
	case "ADO404":
		keys := make([]string, 0, len(rules.RetiredImages))
		for k := range rules.RetiredImages {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		var b strings.Builder
		b.WriteString("### Images\n\nLabels are matched case-insensitively, and matrix variables used as `vmImage: $(var)` are resolved.\n\n| vmImage | Status |\n| --- | --- |\n")
		for _, k := range keys {
			fmt.Fprintf(&b, "| `%s` | %s |\n", k, rules.RetiredImages[k])
		}
		return b.String()
	case "ADO501", "ADO502", "ADO503":
		return fmt.Sprintf("The embedded schema describes %d built-in task versions. Tasks referenced by GUID are not checked.\n", len(v.Root().Tasks()))
	case "ADO701":
		return profileSection("ADO701", "ShellCheck", "shellcheck", "every SC1xxx parse error", scripts.RecommendedShellCheck, scripts.DefaultExcludedShellCheck, "https://www.shellcheck.net/wiki/%s")
	case "ADO702":
		return profileSection("ADO702", "PSScriptAnalyzer", "psscriptanalyzer", "parse errors", scripts.RecommendedPSScriptAnalyzer, nil, "")
	}
	return ""
}

func profileSection(id, tool, key, parse string, recommended, excluded []string, wiki string) string {
	var b strings.Builder
	fmt.Fprintf(&b, "### Rule profile\n\nThe default `recommended` profile reports %s plus:\n\n", parse)
	for _, c := range recommended {
		if wiki != "" {
			fmt.Fprintf(&b, "- [%s](%s)\n", c, fmt.Sprintf(wiki, c))
			continue
		}
		fmt.Fprintf(&b, "- `%s`\n", c)
	}
	if len(excluded) > 0 {
		fmt.Fprintf(&b, "\nThese are never reported unless listed in `include`, because they misfire on pipeline scripts: `%s`.\n", strings.Join(excluded, "`, `"))
	}
	fmt.Fprintf(&b, "\nChoose `all` or `none`, or adjust the set:\n\n```yaml\nscripts:\n  %s:\n    profile: recommended   # recommended | all | none\n    include: []\n    exclude: []\n```\n\n", key)
	fmt.Fprintf(&b, "Findings are reported as `%s/<code>`. Suppress one with `# adolint:disable-next-line %s/<code>` or with %s's own suppression syntax. %s runs from `PATH` and isn't bundled.\n", id, id, tool, tool)
	return b.String()
}

func index(reg *lint.Registry) string {
	var b strings.Builder
	fmt.Fprintf(&b, "---\ntitle: Rules\nnav_order: 4\nhas_children: true\npermalink: /rules/\n---\n%s{%% raw %%}\n", Header)
	b.WriteString("# Rules\n\nThese are all the rules adolint can report. Run `adolint explain <ID>` to see the same information in a terminal.\n\n")
	for _, cat := range categories {
		fmt.Fprintf(&b, "## %s\n\n| ID | Name | Default | Summary |\n| --- | --- | --- | --- |\n", cat)
		for _, r := range reg.All() {
			m := r.Meta()
			if m.Category() != cat {
				continue
			}
			sev := severityText(m)
			if m.DisabledByDefault {
				sev += " (off by default)"
			}
			fmt.Fprintf(&b, "| [%s](%s/) | `%s` | %s | %s |\n", m.ID, m.ID, m.Name, sev, strings.ReplaceAll(m.Summary, "|", "\\|"))
		}
		b.WriteString("\n")
	}
	b.WriteString("{% endraw %}\n")
	return b.String()
}
